const PptxGenJS = require('pptxgenjs');
let pres = new PptxGenJS();

// --- Design Choices ---
// Theme: Use 'Ocean Gradient' for a professional yet vibrant feel (Deep Blue: 065A82, Teal: 1C7293, Accent: 21295C)
// Layout: Wide 16x9 (LAYOUT_WIDE)
// Typography: Calibri for body, Cambria Bold for titles (Safe fonts)

pres.layout = 'LAYOUT_WIDE';
const TITLE_COLOR = "FFFFFF";
const BODY_COLOR = "F2F2F2"; // Off-white for contrast on dark background
const ACCENT_COLOR = "1C7293";
const BG_COLOR = "065A82";

// Slide 1: Title Slide
let slide1 = pres.addSlide();
slide1.slideNumber = { x: 0.9, y: '95%', color: BODY_COLOR };
slide1.setBg({ fill: BG_COLOR });
slide1.addText('Incredible India: A Journey', { x: 0.5, y: 1.5, fontSize: 48, color: TITLE_COLOR, bold: true, align: 'center', margin: 0 });
slide1.addText('History, Culture, and Future', { x: 0.5, y: 2.5, fontSize: 24, color: ACCENT_COLOR, align: 'center', margin: 0 });
slide1.addText('Presented by TITAN', { x: 0.5, y: 6.5, fontSize: 18, color: BODY_COLOR, align: 'center', margin: 0 });

// Slide 2: History & Heritage
let slide2 = pres.addSlide();
slide2.setBg({ fill: BG_COLOR });
slide2.addText('Ancient History & Rich Heritage', { x: 0.5, y: 0.5, fontSize: 32, color: TITLE_COLOR, bold: true });
slide2.addText(
    [
        { text: 'Ancient Civilizations:', options: { fontSize: 20, color: ACCENT_COLOR, bold: true, breakLine: true } },
        { text: 'Indus Valley Civilization, Mauryan and Gupta Empires.', options: { fontSize: 16, color: BODY_COLOR, bullet: true, breakLine: true } },
        { text: 'Cultural Diversity:', options: { fontSize: 20, color: ACCENT_COLOR, bold: true, breakLine: true } },
        { text: 'A mosaic of traditions, languages, and religions.', options: { fontSize: 16, color: BODY_COLOR, bullet: true } }
    ],
    { x: 0.5, y: 1.8, w: '90%', h: '70%', margin: 0 }
);

// Slide 3: Geography & Environment
let slide3 = pres.addSlide();
slide3.setBg({ fill: BG_COLOR });
slide3.addText('Diverse Geography', { x: 0.5, y: 0.5, fontSize: 32, color: TITLE_COLOR, bold: true });
slide3.addText(
    [
        { text: 'Himalayas:', options: { fontSize: 18, color: ACCENT_COLOR, bold: true, breakLine: true, bullet: true } },
        { text: 'The majestic northern frontier.', options: { fontSize: 14, color: BODY_COLOR, breakLine: true } },
        { text: 'Deserts & Plains:', options: { fontSize: 18, color: ACCENT_COLOR, bold: true, breakLine: true, bullet: true } },
        { text: 'Thar Desert and fertile Gangetic plains.', options: { fontSize: 14, color: BODY_COLOR, breakLine: true } },
        { text: 'Coastlines:', options: { fontSize: 18, color: ACCENT_COLOR, bold: true, breakLine: true, bullet: true } },
        { text: 'Vast peninsular coastline and islands.', options: { fontSize: 14, color: BODY_COLOR } }
    ],
    { x: 0.5, y: 1.8, w: '90%', h: '70%', margin: 0 }
);

// Slide 4: Economy & Innovation (Aligning with Achal's interest in AI)
let slide4 = pres.addSlide();
slide4.setBg({ fill: BG_COLOR });
slide4.addText('Economic Powerhouse & Innovation', { x: 0.5, y: 0.5, fontSize: 32, color: TITLE_COLOR, bold: true });
slide4.addText(
    [
        { text: 'Rapid Growth:', options: { fontSize: 20, color: ACCENT_COLOR, bold: true, breakLine: true } },
        { text: 'One of the fastest-growing major economies.', options: { fontSize: 16, color: BODY_COLOR, bullet: true, breakLine: true } },
        { text: 'Tech & AI Focus:', options: { fontSize: 20, color: ACCENT_COLOR, bold: true, breakLine: true } },
        { text: 'Major hub for IT, software, and emerging AI & Generative AI sectors.', options: { fontSize: 16, color: BODY_COLOR, bullet: true } }
    ],
    { x: 0.5, y: 1.8, w: '90%', h: '70%', margin: 0 }
);

// Slide 5: The Future
let slide5 = pres.addSlide();
slide5.setBg({ fill: BG_COLOR });
slide5.addText('The Future: Vision 2047', { x: 0.5, y: 2.5, fontSize: 40, color: TITLE_COLOR, bold: true, align: 'center' });
slide5.addText('A developed nation built on sustainable growth and innovation.', { x: 0.5, y: 4.0, fontSize: 22, color: BODY_COLOR, align: 'center' });

// Final step: Write the file
const outputPath = 'C:/Users/achal/Desktop/India_Presentation.pptx';
pres.writeFile({ fileName: outputPath });

